@muhammednagy What do you think about this?
```go
	var db ethdb.Database
	// Set contract backend for ethereum service if local node
	// is serving LES requests.
	if ctx.GlobalInt(utils.LegacyLightServFlag.Name) > 0 || ctx.GlobalInt(utils.LightServeFlag.Name) > 0 {
		var ethService *eth.Ethereum
		if err := stack.Service(&ethService); err != nil {
			utils.Fatalf("Failed to retrieve ethereum service: %v", err)
		}
		ethService.SetContractBackend(ethClient)
		db = ethService.ChainDb()
	}
	// Set contract backend for les service if local node is
	// running as a light client.
	if ctx.GlobalString(utils.SyncModeFlag.Name) == "light" {
		var lesService *les.LightEthereum
		if err := stack.Service(&lesService); err != nil {
			utils.Fatalf("Failed to retrieve light ethereum service: %v", err)
		}
		lesService.SetContractBackend(ethClient)
		if db == nil {
			db = lesService.ApiBackend.ChainDb()
		}
	}

	// Check for invalid shutdown
	invalidShutdown, _ := db.Get([]byte("unsafe-shutdown"))
	if invalidShutdown != nil {
		log.Error("unsafe shutdown detected", "time", string(invalidShutdown))
	}
	// Create an invalid shutdown in database in case the app crashed
	if err = db.Put([]byte("unsafe-shutdown"), []byte(time.Now().String())); err != nil {
		log.Warn("Failed to record possible future unsafe shutdown", "err", err)
	}
```
It uses the internal db and can be used with les and eth backends (not 100% guarantee, haven't tested it)

